#!/usr/bin/env node
// Issue Auto Responder — uses Claude Code CLI for intelligent wiki search & reply
// Triggered by .github/workflows/issue-responder.yml on issue events

import { execSync } from 'node:child_process'

// ── Step 1: Gather issue context ─────────────────────────────────────────
const issueNumber = process.env.ISSUE_NUMBER
const issueTitle = process.env.ISSUE_TITLE || ''
const issueBody = process.env.ISSUE_BODY || ''
const commentBody = process.env.COMMENT_BODY || ''
const eventName = process.env.EVENT_NAME
const senderLogin = process.env.SENDER_LOGIN || 'unknown'

console.log(`Event: ${eventName} on issue #${issueNumber} by @${senderLogin}`)

// ── Step 2: Fetch existing comments (for issue_comment events) ───────────
let existingComments = ''
if (eventName === 'issue_comment') {
  try {
    const commentsJson = execSync(
      `gh issue view ${issueNumber} --comments --json comments --jq '.comments[] | "\\(.author.login): \\(.body)"'`,
      { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] },
    )
    existingComments = commentsJson.trim()
    console.log('Loaded existing comments.')
  } catch {
    console.log('No existing comments.')
  }
}

// ── Step 3: Build prompt ──────────────────────────────────────────────────
let issueContext = ''
if (eventName === 'issues') {
  issueContext = `**Issue 内容：**\n${issueBody || '(无内容)'}`
} else {
  issueContext = `**Issue 原始内容：**\n${issueBody || '(无内容)'}`
  if (existingComments) {
    issueContext += `\n\n**已有评论：**\n${existingComments}`
  }
  issueContext += `\n\n**最新评论 (@${senderLogin})：**\n${commentBody}`
}

const prompt = `你是本仓库的 AI 研究助手。仓库中有一个 wiki/ 目录，包含以下子目录：
- wiki/concepts/ — 技术概念条目
- wiki/entities/ — 实体（模型、团队、工具等）
- wiki/events/ — 时间线事件
- wiki/sources/ — 原始资料
- wiki/overview.md — 整体概览

每个 wiki 文件都有 YAML frontmatter，包含 type、title、tags、related 等元数据。

请根据以下 Issue 内容，搜索并阅读相关的 wiki 文件，然后给出专业、准确的回答。

## Issue #${issueNumber}: ${issueTitle}

${issueContext}

回答要求：
1. 先用 Glob 和 Grep 搜索相关 wiki 文件，再阅读内容
2. 基于实际 wiki 内容回答，不要编造
3. 使用 Markdown 格式
4. 在回答末尾附上「参考来源」章节，列出引用的 wiki 文件路径
5. 如果 wiki 中没有相关内容，可以基于你的知识回答，但需说明`

// ── Step 4: Call Claude Code CLI ──────────────────────────────────────────
console.log('\nCalling Claude Code CLI...')

let responseText
try {
  responseText = execSync(
    `claude -p --effort medium --model glm-5.1 --max-budget-usd 2 --allowedTools Read,Glob,Grep --max-turns 6`,
    {
      input: prompt,
      encoding: 'utf8',
      timeout: 300000, // 5 min timeout
    },
  ).trim()
} catch (err) {
  console.error('Claude CLI failed:', err.message)
  if (err.stdout) {
    responseText = err.stdout.trim()
  }
  if (!responseText) {
    console.error('No output captured. Exiting.')
    process.exit(1)
  }
}

console.log('Response generated successfully.')

// ── Step 5: Post comment ──────────────────────────────────────────────────
const commentBody_out = `${responseText}

---
*Auto-generated by [issue-responder](https://github.com/BITDeeper/llm_wiki_notebook/actions/workflows/issue-responder.yml)*`

import { writeFileSync } from 'node:fs'
const tmpFile = `/tmp/comment-${issueNumber}.md`
writeFileSync(tmpFile, commentBody_out, 'utf8')

console.log('\nPosting comment...')
try {
  const result = execSync(
    `gh issue comment ${issueNumber} --body-file "${tmpFile}"`,
    { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] },
  )
  console.log(`Comment posted: ${result.trim()}`)
} catch (err) {
  console.error('Failed to post comment:', err.message)
  console.log('\n--- Response Content ---\n')
  console.log(responseText)
  process.exit(1)
}
